477	function parseThresholds(thresholdStrings?: string[]): { thresholds: Record<string, number>; validMetricIds: string[] } {
478	  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];
479	
480	  if (!thresholdStrings || thresholdStrings.length === 0) {
481	    return { thresholds: {}, validMetricIds };
482	  }
483	
484	  const thresholds: Record<string, number> = {};
485	
486	  for (const thresholdStr of thresholdStrings) {
487	    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
488	    if (!match) {
489	      log.error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
490	      log.error(`Valid metric ids: ${validMetricIds.join(', ')}`);
491	      process.exit(2);
492	    }
493	
494	    const metricId = match[1];
495	    const minValue = parseFloat(match[2]);
496	
497	    if (minValue < 0 || minValue > 1) {
498	      log.error(`Threshold value out of range: ${minValue}. Must be between 0 and 1.`);
499	      process.exit(2);
500	    }
501	
502	    if (!validMetricIds.includes(metricId)) {
503	      log.error(`Unknown metric: ${metricId}`);
504	      log.error(`Valid metric ids: ${validMetricIds.join(', ')}`);
505	      process.exit(2);
506	    }
507	
508	    thresholds[metricId] = minValue;
509	  }
510	
511	  return { thresholds, validMetricIds };
512	}
